using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.LoyaltyDiscount;

public sealed class CalculatePayableTotalTests
{
    private static CalculatePayableTotal CreateCalculatePayableTotal() =>
        new(new LoyaltyDiscountPolicy());

    [Theory]
    [InlineData(10_000, 9_500)]
    [InlineData(20_000, 19_000)]
    [InlineData(5_000, 4_750)]
    public void WhenCustomerIsGoldTier_ShouldGetFivePercentOffSubtotal(
        int subtotalCents, int expectedPayableTotalCents)
    {
        var useCase = CreateCalculatePayableTotal();

        var actualPayableTotalCents = useCase.For(subtotalCents, LoyaltyTier.Gold);

        Assert.Equal(expectedPayableTotalCents, actualPayableTotalCents);
    }

    [Fact]
    public void WhenGoldTierCustomerHasEmptyBasket_ShouldPayNothing()
    {
        var useCase = CreateCalculatePayableTotal();

        var actualPayableTotalCents = useCase.For(0, LoyaltyTier.Gold);

        Assert.Equal(0, actualPayableTotalCents);
    }
}
EOF
